// ─────────────────────────────────────────────────────────────────────────────
// MealDrama Dish Library — Scalable to 10,000 dishes via variation dimensions
// Each base dish expands by: cooking style × meal context × region override × add-ons
// ─────────────────────────────────────────────────────────────────────────────

export type Region = 'north' | 'south' | 'west' | 'east' | 'central' | 'northeast' | 'all';
export type Category = 'breakfast' | 'lunch' | 'dinner' | 'snacks' | 'winter-lunch' | 'summer-lunch' | 'winter-dinner' | 'summer-dinner';
export type DishType = 'veg' | 'non-veg' | 'vegan' | 'eggitarian';
export type Weight = 'light' | 'medium' | 'heavy';

export type IngredientCategory = 'produce' | 'dairy' | 'grains' | 'proteins' | 'spices' | 'pantry' | 'breads' | 'snacks';

export const GravyType = {
  DEFAULT: 'DEFAULT',
  TADKA: 'TADKA',
  GRAVY: 'GRAVY',
  DRY: 'DRY',
  CURRY: 'CURRY',
  FRIED: 'FRIED',
  STEAMED: 'STEAMED',
  ROASTED: 'ROASTED',
  SMOKED: 'SMOKED',
} as const;

export type GravyType = (typeof GravyType)[keyof typeof GravyType];

const GRAVY_LABELS: Record<string, string> = {
  DEFAULT: 'Default',
  TADKA: 'Tadka',
  GRAVY: 'Gravy',
  DRY: 'Dry',
  CURRY: 'Curry',
  FRIED: 'Fried',
  STEAMED: 'Steamed',
  ROASTED: 'Roasted',
  SMOKED: 'Smoked',
};



export interface Ingredient {
    name: string;
    quantity: number;
    unit: string;
    category: IngredientCategory;
    inStock?: boolean;
}

export interface DishVariant {
    id: string;
    name: string;
    cookingStyle?: string;
    addOn?: string;
    mealContext?: Category;
    regionOverride?: string;
    baseStyle?: string;
    tags?: string[];
    healthCategories?: string[];
    // Optional: regional accompaniments (sides or breads) that pair with this variant
    accompaniments?: string[];
    // Ingredients for shopping list generation
    ingredients?: Ingredient[];
    // Optional: preparation or serving tip
    tip?: string;
}

export interface Dish {
    id: string;
    name: string;
    icon: string;
    region: Region;
    states: string[];
    category: Category[];
    type: DishType;
    weight: Weight;
    nutrition: string[];
    tags: string[];
    variants: DishVariant[];
    gravyType?: string;
    rotiOptions?: string[];
    riceOptions?: string[];
    sideOptions?: string[];
    beverageOptions?: string[];
    diet?: 'vegan' | 'veg' | 'egg' | 'non-veg';
    defaultPairings?: {
      gravy?: string | null;
      roti?: string | null;
      rice?: string | null;
      sides?: string[];
      beverages?: string[];
      dessert?: string[];
    };
    description?: string;
    season?: string[];
    prepTime?: number;
    /** Nutritional values (calories in kcal, protein in grams) */
    calories?: number;
    protein?: number;
}

// ─── Helper: auto-generate variants ──────────────────────────────────────────
// Self-carb dishes (puri, paratha, naan, rice, biryani) already contain carbs
// so they should NOT get "+ Rice" or "+ Roti" variants.
const SELF_CARB_TAGS = new Set(['puri', 'paratha', 'naan', 'rice', 'biryani', 'bread', 'pulao', 'roti']);

const addOnVariants = (base: string, id: string, tags?: string[]): DishVariant[] => {
  const isSelfCarb = tags?.some(t => SELF_CARB_TAGS.has(t)) ?? false;
  return [
    ...(isSelfCarb ? [] : [{ id: `${id}-rice`, name: `${base} with Rice`, addOn: 'with rice', mealContext: 'lunch' } as const]),
    ...(isSelfCarb ? [] : [{ id: `${id}-roti`, name: `${base} with Roti`, addOn: 'with roti', mealContext: 'dinner' } as const]),
    { id: `${id}-bowl`, name: `${base} Bowl`, addOn: 'standalone', mealContext: 'lunch' },
    { id: `${id}-lite`, name: `${base} Lite (Dinner)`, addOn: 'light portion', mealContext: 'dinner' },
    { id: `${id}-thali`, name: `${base} Thali`, addOn: 'thali set', mealContext: 'lunch' },
  ];
};

const cookingVariants = (base: string, id: string, styles: string[]): DishVariant[] =>
    styles.map(style => ({ id: `${id}-${style.toLowerCase()}`, name: `${base} ${style}`, cookingStyle: style }));

